from __future__ import annotations

from api.operator_console_bounded import CONSOLE_HTML_V28

AUTH_SCRIPT = r"""
<style>
.auth-panel{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.auth-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.auth-grid select,.auth-grid textarea{width:100%;border:1px solid #cbdced;border-radius:10px;padding:10px;font:inherit;background:#fff}.auth-grid textarea{grid-column:1/-1;min-height:90px;resize:vertical}.auth-grid label.confirm{grid-column:1/-1;display:flex;align-items:flex-start;gap:8px;padding:12px;background:#fff8ea;border:1px solid #f2dfb8;border-radius:10px}.auth-grid button{grid-column:1/-1;border:0;border-radius:10px;padding:12px;background:#0b2f61;color:#fff;font-weight:800;cursor:pointer}.auth-grid button:disabled{opacity:.55;cursor:not-allowed}.auth-box{border:1px solid #e2edf8;border-radius:12px;padding:12px;background:#fbfdff;margin-bottom:10px}.auth-box ul{margin:7px 0 0;padding-left:20px}.auth-status{min-height:20px;margin-top:10px;font-size:13px}.auth-status.ok{color:#147a46}.auth-status.err{color:#b42318}.scope-warning{font-weight:800;color:#9a5a00}@media(max-width:620px){.auth-grid{grid-template-columns:1fr}}
</style>
<script>
async function loadAuthorizationControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('authorization-control');if(!box){box=document.createElement('section');box.id='authorization-control';box.className='auth-panel';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Human Authorization Review</h3><div class="muted">Checking current bounded action packet…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/authorization-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok)throw new Error('authorization context unavailable');const d=await r.json();if(!d.current_action){box.innerHTML='<h3>Human Authorization Review</h3><div class="muted">Prepare a bounded action packet first.</div>';return}const a=d.current_action;const prohibited=(a.prohibited_effects||[]).map(x=>`<li>${esc(x)}</li>`).join('');const latest=d.latest_authorization?`Latest disposition: ${esc(d.latest_authorization.decision)} · ${esc(d.latest_authorization.state)}`:'No human authorization has been recorded for this packet.';box.innerHTML=`<h3>Human Authorization Review</h3><div class="auth-box"><strong>${esc(a.action_kind)}</strong><div><b>Objective:</b> ${esc(a.objective)}</div><div><b>Scope:</b> ${esc(a.scope||'Not specified')}</div><div><b>Target:</b> ${esc(a.target_capability||'Not specified')}</div><div class="scope-warning">Any approval from this panel is for execution review only. It does not authorize execution or dispatch.</div></div><div class="auth-box"><strong>Prohibited effects remain prohibited</strong><ul>${prohibited}</ul></div><div class="muted" style="margin-bottom:10px">${latest}</div><form id="authorization-form" class="auth-grid"><select id="auth-decision"><option value="approve_for_execution_review">Approve for execution review only</option><option value="request_changes">Request changes</option><option value="hold">Hold</option><option value="reject">Reject</option></select><div></div><textarea id="auth-rationale" placeholder="Rationale / review note"></textarea><label class="confirm"><input type="checkbox" id="auth-confirm"><span>I confirm that approval is limited to <strong>execution review only</strong>. It does not permit execution, dispatch, trading, capital movement, purchases, outreach, or credential changes.</span></label><button id="auth-submit">Record human disposition</button></form><div id="auth-status" class="auth-status"></div>`;const decision=box.querySelector('#auth-decision');const confirm=box.querySelector('#auth-confirm');function sync(){confirm.disabled=decision.value!=='approve_for_execution_review';if(confirm.disabled)confirm.checked=false}decision.onchange=sync;sync();box.querySelector('#authorization-form').addEventListener('submit',async(e)=>{e.preventDefault();const status=box.querySelector('#auth-status');const btn=box.querySelector('#auth-submit');status.textContent='';status.className='auth-status';btn.disabled=true;try{const approve=decision.value==='approve_for_execution_review';const rationale=box.querySelector('#auth-rationale').value;if(approve&&!confirm.checked)throw new Error('Execution-review-only scope confirmation is required.');if(approve&&!rationale.trim())throw new Error('Approval rationale is required.');const csrf=await loadConsoleCsrf();const body={decision:decision.value,reviewer_label:'operator-console',rationale:rationale,scope_confirmed:approve?confirm.checked:false};const rr=await fetch('/operator/api/bounded-actions/'+encodeURIComponent(a.action_packet_id)+'/authorization',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify(body)});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Authorization rejected')}const x=await rr.json();status.textContent=`Disposition recorded: ${x.authorization.state}. Execution permitted: false. Dispatch permitted: false.`;status.className='auth-status ok';setTimeout(()=>loadCase(recordId),300)}catch(err){status.textContent=String(err.message||err);status.className='auth-status err'}finally{btn.disabled=false}})}catch(_){box.innerHTML='<h3>Human Authorization Review</h3><div class="muted">Authorization context unavailable.</div>'}}
const _v28LoadCase=loadCase;loadCase=async function(id){await _v28LoadCase(id);await loadAuthorizationControl(id)};setTimeout(()=>{if(selected)loadAuthorizationControl(selected)},1000);
</script>
"""

CONSOLE_HTML_V29 = CONSOLE_HTML_V28.replace("</body>", AUTH_SCRIPT + "</body>")
